## 8. Status Filter Buttons on Card List Screen (Lines 1850–1919)

**File:** `D:\Desktop\marine\public\index.html`

```javascript
const { navigate } = useContext(NavCtx);
const { employee } = useContext(AuthCtx);
const [allCards, setAllCards] = useState([]);
const [filter, setFilter] = useState(params.filterStatus || "all");
const [search, setSearch] = useState("");
const [loading, setLoading] = useState(true);

useEffect(() => {
  setLoading(true);
  const qs = new URLSearchParams();
  if (search) qs.set("q", search);
  api("GET", `/cards?${qs}`)
    .then((data) => {
      setAllCards(data);
      setLoading(false);
    })
    .catch(() => setLoading(false));
}, [search]);

const cards = allCards.filter(c => filter === "all" || c.status === filter);

return (
  <div>
    {/* search bar + new button */}
    <div className="pipeline sticky-top">
      {["all", ...STATUS_ORDER].map((s) => {
        const cfg =
          s === "all"
            ? { label: "ALL", color: "var(--text2)", bg: "var(--surface2)" }
            : STATUS_CONFIG[s];
