Users can manually toggle between `"fall"` and `"spring"` checklists via chip buttons, regardless of the auto-detected season.

### Toggle item logic (lines 3520–3547)
```javascript
const toggle = async (key) => {
  const updated = { ...items, [key]: !items[key] };
  setLocalChecklists((prev) => {
    const idx = prev.findIndex((c) => c.checklist_type === activeList);
    const newEntry = {
      checklist_type: activeList,
      items_json: JSON.stringify(updated),
    };
    if (idx >= 0) {
      const n = [...prev];
      n[idx] = newEntry;
      return n;
    }
    return [...prev, newEntry];
  });
  try {
    await api("POST", `/cards/${card.id}/checklists`, {
      checklist_type: activeList,
      items_json: JSON.stringify(updated),
    });
    reload();
  } catch (e) {
    showToast("Save failed");
    reload();
  }
